import type { jsPDF } from 'jspdf';

/** Same asset End of Life PDF already embeds. */
export const HTB_PDF_LOGO_SRC = '/images/logo/Logo_Side_Black.png';
export const HTB_PDF_LOGO_WIDTH = 699;
export const HTB_PDF_LOGO_HEIGHT = 306;
export const HTB_PDF_LOGO_DATA_URL = "data:image/png;base64,";

export function htbPdfLogoBox(footerY: number) {
  const logoHeight = 8;
  const logoWidth = logoHeight * (HTB_PDF_LOGO_WIDTH / HTB_PDF_LOGO_HEIGHT);
  const logoY = footerY - logoHeight + 1.5;
  return { logoHeight, logoWidth, logoY };
}

export async function loadHtbPdfLogo(): Promise<string> {
  try {
    const src =
      typeof window !== 'undefined' ? new URL(HTB_PDF_LOGO_SRC, window.location.origin).href : HTB_PDF_LOGO_SRC;
    const response = await fetch(src);
    if (response.ok) {
      const blob = await response.blob();
      const dataUrl = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ''));
        reader.onerror = () => reject(reader.error);
        reader.readAsDataURL(blob);
      });
      if (dataUrl.startsWith('data:image/')) return dataUrl;
    }
  } catch {
    // Fall back to the bundled PNG so the export cannot stay text-only.
  }
  return HTB_PDF_LOGO_DATA_URL;
}

export function stampHtbPdfLogo(
  pdf: jsPDF,
  margin: number,
  footerY: number,
  logoDataUrl: string = HTB_PDF_LOGO_DATA_URL,
) {
  const { logoHeight, logoWidth, logoY } = htbPdfLogoBox(footerY);
  pdf.addImage(logoDataUrl, 'PNG', margin, logoY, logoWidth, logoHeight);
  return { logoHeight, logoWidth, logoY };
}
